public class CharacterTable : MonoBehaviour
{
    [SerializeField] TextAsset csv;
    Dictionary<string, CharacterRow> rows = new Dictionary<string, CharacterRow>();

    void Awake()
    {
        string[] lines = csv.text.Split('\n');
        for (int i = 1; i < lines.Length; i++)
        {
            string line = lines[i].Trim();
            if (line == "") continue;

            string[] c = line.Split(',');
            if (c.Length < 5)
            {
                Debug.LogError((i + 1) + "번째 줄: 칸이 부족해요");
                continue;
            }

            CharacterRow row = new CharacterRow();
            row.id = c[0];
            row.name = c[1];
            int.TryParse(c[2], out row.hp);
            int.TryParse(c[3], out row.atk);
            float.TryParse(c[4], NumberStyles.Float, CultureInfo.InvariantCulture, out row.speed);

            if (rows.ContainsKey(row.id))
                Debug.LogError("중복 ID: " + row.id);
            else
                rows.Add(row.id, row);
        }
    }

    public CharacterRow Get(string id)
    {
        if (rows.TryGetValue(id, out CharacterRow row)) return row;
        Debug.LogError("없는 캐릭터 ID: " + id);
        return null;
    }
}

