[MenuItem("Tools/캐릭터 테이블 가져오기")]
static void Import()
{
    TextAsset csv = AssetDatabase.LoadAssetAtPath<TextAsset>("Assets/Tables/Characters.csv");
    string[] lines = csv.text.Split('\n');

    for (int i = 1; i < lines.Length; i++)
    {
        string line = lines[i].Trim();
        if (line == "") continue;
        string[] c = line.Split(',');

        string path = "Assets/Data/Characters/" + c[0] + ".asset";
        CharacterData data = AssetDatabase.LoadAssetAtPath<CharacterData>(path);

        if (data == null)
        {
            data = ScriptableObject.CreateInstance<CharacterData>();
            AssetDatabase.CreateAsset(data, path);
        }

        data.id = c[0];
        data.displayName = c[1];
        data.maxHp = int.Parse(c[2]);
        data.icon = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/Icons/" + c[0] + ".png");

        EditorUtility.SetDirty(data);
    }

    AssetDatabase.SaveAssets();
    Debug.Log("캐릭터 테이블 가져오기 완료");
}

public class CharacterSpawner : MonoBehaviour
{
    [SerializeField] CharacterTable table;

    public IEnumerator Spawn(string id, Vector3 pos)
    {
        CharacterRow row = table.Get(id);
        if (row == null) yield break;

        var h = Addressables.InstantiateAsync(row.prefab, pos, Quaternion.identity);
        yield return h;

        if (h.Status != AsyncOperationStatus.Succeeded)
        {
            Debug.LogError(id + "의 프리팹 로드 실패: " + row.prefab);
            yield break;
        }

        Character ch = h.Result.GetComponent<Character>();
        ch.Init(row);
    }
}

public class Character : MonoBehaviour
{
    [SerializeField] Image portrait;

    string id;
    int currentHp;
    int atk;
    AsyncOperationHandle<Sprite> iconHandle;

    public void Init(CharacterRow row)
    {
        id = row.id;
        currentHp = row.hp;
        atk = row.atk;
        StartCoroutine(LoadIcon(row.icon));
    }

    IEnumerator LoadIcon(string address)
    {
        iconHandle = Addressables.LoadAssetAsync<Sprite>(address);
        yield return iconHandle;
        if (iconHandle.Status == AsyncOperationStatus.Succeeded)
            portrait.sprite = iconHandle.Result;
    }

    void OnDestroy()
    {
        if (iconHandle.IsValid())
            Addressables.Release(iconHandle);
    }
}
